CREATE TABLE IF NOT EXISTS catalog_transfer_sources(source TEXT PRIMARY KEY,last_success_at INTEGER,full_started_at INTEGER,full_verified_at INTEGER,weekly_enabled INTEGER NOT NULL DEFAULT 0 CHECK(weekly_enabled IN (0,1)),updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS catalog_transfer_runs(id TEXT PRIMARY KEY,source TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN ('trial','full','delta')),actor TEXT NOT NULL,status TEXT NOT NULL,window_start INTEGER NOT NULL,window_end INTEGER NOT NULL,cursor INTEGER NOT NULL DEFAULT 0,scan_done INTEGER NOT NULL DEFAULT 0,lease_token TEXT,lease_until INTEGER NOT NULL DEFAULT 0,api_calls INTEGER NOT NULL DEFAULT 0,started_at TEXT NOT NULL,updated_at TEXT NOT NULL,finished_at TEXT,error TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS catalog_transfer_active_idx ON catalog_transfer_runs(source) WHERE status IN ('running','paused');
CREATE INDEX IF NOT EXISTS catalog_transfer_time_idx ON catalog_transfer_runs(started_at DESC,id);
CREATE TABLE IF NOT EXISTS catalog_transfer_items(run_id TEXT NOT NULL,app_id INTEGER NOT NULL,source_name TEXT NOT NULL,source_modified INTEGER NOT NULL DEFAULT 0,lane TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,next_retry_at INTEGER NOT NULL DEFAULT 0,game_id TEXT,prepared TEXT,approval TEXT,error TEXT,audit_id TEXT,updated_at TEXT NOT NULL,PRIMARY KEY(run_id,app_id));
CREATE INDEX IF NOT EXISTS catalog_transfer_queue_idx ON catalog_transfer_items(run_id,status,next_retry_at,app_id);
CREATE INDEX IF NOT EXISTS catalog_transfer_deferred_idx ON catalog_transfer_items(status,next_retry_at,run_id,app_id);
